sql:
-- Offline clone only. Existing owner/session are simulated DB claims, NOT issued JWTs.
-- All synthetic settings, activation, publication and payroll changes roll back.
CREATE TEMP TABLE common_flow_scope AS SELECT p.company_id,p.worker_id,p.period_start,p.period_end,p.id payroll_id
FROM public.payroll_statements p WHERE md5(to_jsonb(p)::text)='acdb78113fd628c32411c8ce73086213';
DO $scope$
DECLARE s record; typ text;
BEGIN
 IF (SELECT count(*) FROM common_flow_scope)<>1 THEN RAISE EXCEPTION 'protected original payroll differs'; END IF;
 SELECT * INTO s FROM common_flow_scope;
 IF s.period_start<>date_trunc('month',current_timestamp AT TIME ZONE 'Asia/Tokyo')::date
 THEN RAISE EXCEPTION 'current-month payroll required; never bypass historical publication guard'; END IF;
 SELECT pay_type INTO STRICT typ FROM public.worker_payroll_settings WHERE company_id=s.company_id AND worker_id=s.worker_id;
 IF typ NOT IN ('daily','hourly','monthly') OR EXISTS(SELECT 1 FROM public.payroll_statements WHERE id=s.payroll_id AND
  (automatic_calculation IS DISTINCT FROM true OR workflow_state IS DISTINCT FROM 'draft'))
 THEN RAISE EXCEPTION 'target must be legal automatic draft'; END IF;
 IF EXISTS(SELECT 1 FROM company_common_allowance_private.items)
 OR EXISTS(SELECT 1 FROM company_common_allowance_private.state)
 THEN RAISE EXCEPTION 'new common storage is not empty'; END IF;
 IF (SELECT count(*) FROM public.company_members WHERE company_id=s.company_id AND role::text='owner')<>1
 THEN RAISE EXCEPTION 'unique existing owner required'; END IF;
END $scope$;
CREATE TEMP TABLE common_flow_protected AS SELECT to_jsonb(p) value FROM public.payroll_statements p
WHERE p.automatic_calculation IS DISTINCT FROM true OR p.workflow_state IS DISTINCT FROM 'draft';
CREATE TEMP TABLE common_flow_outside_type AS SELECT to_jsonb(p) value FROM public.payroll_statements p
JOIN common_flow_scope target ON true LEFT JOIN public.worker_payroll_settings settings
ON settings.company_id=p.company_id AND settings.worker_id=p.worker_id
WHERE p.company_id<>target.company_id OR p.period_start<target.period_start
OR settings.pay_type IS DISTINCT FROM (SELECT pay_type FROM public.worker_payroll_settings WHERE company_id=target.company_id AND worker_id=target.worker_id);
CREATE TEMP TABLE common_flow_source AS SELECT jsonb_build_object(
 'rates',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]') FROM public.company_rate_settings t),
 'settings',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]') FROM public.worker_payroll_settings t),
 'tax_conditions',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]') FROM payroll_tax_private.worker_conditions t),
 'attendance',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]') FROM public.attendance_entries t)) value;
CREATE TEMP TABLE common_flow_result(value jsonb);
DO $flow$
DECLARE s record; typ text; actor uuid; sid uuid; common_before jsonb; common_after jsonb; legacy jsonb;
 items jsonb; publication_source jsonb; first_result jsonb; repeated jsonb; unit_detail jsonb;
 baseline public.payroll_statements; updated public.payroll_statements;
 save_request uuid:=gen_random_uuid(); publish_request uuid:=gen_random_uuid(); rejected boolean;
 expected_tax jsonb; baseline_tax jsonb; legacy_basis bigint; expected_deductions bigint; premium record; fixed_key text;
 common_earning uuid; common_deduction uuid; before_retry jsonb; source_after jsonb;
BEGIN
 SELECT * INTO s FROM common_flow_scope;
 SELECT pay_type INTO STRICT typ FROM public.worker_payroll_settings WHERE company_id=s.company_id AND worker_id=s.worker_id;
 SELECT user_id INTO STRICT actor FROM public.company_members WHERE company_id=s.company_id AND role::text='owner';
 SELECT id INTO sid FROM auth.sessions WHERE user_id=actor AND (not_after IS NULL OR not_after>clock_timestamp())
 ORDER BY created_at DESC NULLS LAST,id LIMIT 1;
 IF sid IS NULL THEN RAISE EXCEPTION 'existing live owner session required; no synthetic session will be inserted'; END IF;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated','session_id',sid)::text,true);
 -- Establish a current calculated baseline without common activation, using real stored sources.
 PERFORM private.refresh_automatic_payroll(s.company_id,s.worker_id,s.period_start);
 PERFORM private.sync_payroll_attendance_detail(s.company_id,s.worker_id,s.period_start);
 SELECT * INTO STRICT baseline FROM public.payroll_statements WHERE id=s.payroll_id;
 IF baseline.calculation_blocked THEN RAISE EXCEPTION 'baseline payroll calculation is incomplete'; END IF;
 EXECUTE 'SET LOCAL ROLE authenticated';
 common_before:=public.read_company_common_allowances_admin(s.company_id);
 SELECT jsonb_agg(jsonb_build_object('slot',x->'slot','id',x->'id','generation',x->'generation',
 'name',x->'name','source_unit',x->'source_unit','amount_yen',x->'amount_yen') ORDER BY ord)
 INTO legacy FROM jsonb_array_elements(common_before->'legacy_refs') WITH ORDINALITY e(x,ord);
 items:=jsonb_build_array(
 jsonb_build_object('id',null,'client_key','isolated-earning','section','earning','unit','month','name','隔離検証用・共通支給','amount_yen',1000),
 jsonb_build_object('id',null,'client_key','isolated-deduction','section','deduction','unit','month','name','隔離検証用・共通控除','amount_yen',250));
 common_after:=public.save_company_common_allowances(s.company_id,typ,(common_before->>'version')::bigint,
 common_before->'expected_source',save_request,items,legacy,true);
 repeated:=public.save_company_common_allowances(s.company_id,typ,(common_before->>'version')::bigint,
 common_before->'expected_source',save_request,items,legacy,true);
 IF repeated IS DISTINCT FROM common_after THEN RAISE EXCEPTION 'same save request changed its result'; END IF;
 SELECT (x->>'id')::uuid INTO STRICT common_earning FROM jsonb_array_elements(common_after->'id_map') x WHERE x->>'client_key'='isolated-earning';
 SELECT (x->>'id')::uuid INTO STRICT common_deduction FROM jsonb_array_elements(common_after->'id_map') x WHERE x->>'client_key'='isolated-deduction';
 rejected:=false;
 BEGIN
  PERFORM public.save_company_common_allowances(s.company_id,typ,(common_before->>'version')::bigint,
   common_before->'expected_source',gen_random_uuid(),items,legacy,true);
 EXCEPTION WHEN SQLSTATE '40001' THEN rejected:=true; END;
 IF NOT rejected THEN RAISE EXCEPTION 'stale common save was not rejected'; END IF;
 EXECUTE 'RESET ROLE';
 -- Explicit, test-only cutover. No public activation API exists in the reviewed candidate.
 INSERT INTO company_common_allowance_private.payroll_activation VALUES(s.company_id,s.period_start);
 EXECUTE 'SET LOCAL ROLE authenticated';
 publication_source:=public.read_company_common_payroll_publications(s.company_id);
 first_result:=public.publish_company_common_payroll(s.company_id,typ,s.period_start,
 (publication_source->>'common_version')::bigint,publication_source->'common_source',
 (publication_source->>'timeline_version')::bigint,publish_request);
 EXECUTE 'RESET ROLE';
 SELECT * INTO STRICT updated FROM public.payroll_statements WHERE id=s.payroll_id;
 baseline_tax:=baseline.detail->'tax_calculation';
 IF baseline_tax IS NULL OR baseline_tax='null'::jsonb THEN
  expected_deductions:=baseline.deductions+250;
  IF updated.detail->'tax_calculation' IS NOT NULL AND updated.detail->'tax_calculation'<>'null'::jsonb
  THEN RAISE EXCEPTION 'unregistered tax/insurance conditions were invented'; END IF;
  FOREACH fixed_key IN ARRAY ARRAY['所得税','社会保険','雇用保険料','健康保険料','厚生年金保険','介護保険料','子ども・子育て支援金'] LOOP
   IF updated.detail->fixed_key IS DISTINCT FROM baseline.detail->fixed_key
   THEN RAISE EXCEPTION 'saved fixed tax/insurance detail was changed'; END IF;
  END LOOP;
 ELSE
  SELECT baseline.deductions-(baseline_tax->>'income_tax_yen')::bigint-(baseline_tax->>'social_yen')::bigint
   +round(coalesce(settings.income_tax_monthly,0))+round(coalesce(settings.social_insurance_monthly,0))+250
  INTO legacy_basis FROM public.worker_payroll_settings settings WHERE company_id=s.company_id AND worker_id=s.worker_id;
  expected_tax:=payroll_tax_private.calculate(s.company_id,s.worker_id,s.period_start,s.period_end,updated.gross_pay,legacy_basis);
  IF expected_tax IS NULL OR expected_tax->>'blocked'='true'
  OR updated.detail->'tax_calculation' IS DISTINCT FROM expected_tax
  OR expected_tax->'conditions' IS DISTINCT FROM baseline_tax->'conditions'
  OR expected_tax->'condition_version' IS DISTINCT FROM baseline_tax->'condition_version'
  OR expected_tax->'conditions_start' IS DISTINCT FROM baseline_tax->'conditions_start'
  OR expected_tax->'deduction_overrides' IS DISTINCT FROM baseline_tax->'deduction_overrides'
  OR updated.detail->'所得税' IS DISTINCT FROM expected_tax->'income_tax_yen'
  THEN RAISE EXCEPTION 'common earnings lost tax/insurance conditions or proper recalculation'; END IF;
  expected_deductions:=(expected_tax->>'deductions')::bigint;
  IF expected_tax#>>'{conditions,insurance_mode}'='rates' THEN
   FOR premium IN SELECT key,value FROM jsonb_each(expected_tax->'premiums') LOOP
    IF updated.detail->premium.key IS DISTINCT FROM premium.value
    THEN RAISE EXCEPTION 'insurance premium breakdown differs from proper recalculation'; END IF;
   END LOOP;
  ELSIF updated.detail->'社会保険' IS DISTINCT FROM expected_tax->'social_yen'
  THEN RAISE EXCEPTION 'legacy social insurance amount was lost'; END IF;
 END IF;
 IF updated.calculation_blocked OR updated.gross_pay IS DISTINCT FROM baseline.gross_pay+1000
 OR updated.deductions IS DISTINCT FROM expected_deductions
 OR updated.net_pay IS DISTINCT FROM greatest(0,updated.gross_pay-updated.deductions)
 OR updated.detail->'住民税' IS DISTINCT FROM baseline.detail->'住民税'
 OR updated.detail->'resident_tax_source' IS DISTINCT FROM baseline.detail->'resident_tax_source'
 THEN RAISE EXCEPTION 'common payroll totals or saved resident tax differ'; END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(updated.detail->'unit_resolution'->'items') x
 WHERE x->>'id'=common_earning::text AND x->>'origin'='company_common' AND x->>'section'='earning'
 AND (x->>'amount_yen')::numeric=1000 AND (x->>'quantity')::numeric=1)
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(updated.detail->'unit_resolution'->'items') x
 WHERE x->>'id'=common_deduction::text AND x->>'origin'='company_common' AND x->>'section'='deduction'
 AND (x->>'amount_yen')::numeric=250 AND (x->>'quantity')::numeric=1)
 THEN RAISE EXCEPTION 'saved payroll common breakdown is incomplete'; END IF;
 before_retry:=to_jsonb(updated);
 EXECUTE 'SET LOCAL ROLE authenticated';
 unit_detail:=public.payroll_unit_conditions(s.company_id,s.worker_id,s.period_start);
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(unit_detail->'company_common'->'items') x WHERE x->>'id'=common_earning::text AND (x->>'amount_yen')::numeric=1000)
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(unit_detail->'company_common'->'items') x WHERE x->>'id'=common_deduction::text AND (x->>'amount_yen')::numeric=250)
 THEN RAISE EXCEPTION 'public common detail differs from saved payroll'; END IF;
 repeated:=public.publish_company_common_payroll(s.company_id,typ,s.period_start,
 (publication_source->>'common_version')::bigint,publication_source->'common_source',
 (publication_source->>'timeline_version')::bigint,publish_request);
 IF repeated IS DISTINCT FROM first_result THEN RAISE EXCEPTION 'same publish request changed its receipt'; END IF;
 rejected:=false;
 BEGIN
  PERFORM public.publish_company_common_payroll(s.company_id,typ,s.period_start,
  (publication_source->>'common_version')::bigint,publication_source->'common_source',
  (publication_source->>'timeline_version')::bigint,gen_random_uuid());
 EXCEPTION WHEN SQLSTATE '40001' THEN rejected:=true; END;
 IF NOT rejected THEN RAISE EXCEPTION 'stale publication was not rejected'; END IF;
 EXECUTE 'RESET ROLE';
 IF (SELECT to_jsonb(p) FROM public.payroll_statements p WHERE p.id=s.payroll_id) IS DISTINCT FROM before_retry
 THEN RAISE EXCEPTION 'retry/CAS rejection changed saved payroll'; END IF;
 IF EXISTS(SELECT 1 FROM common_flow_protected old WHERE NOT EXISTS(SELECT 1 FROM public.payroll_statements p WHERE to_jsonb(p)=old.value))
 OR EXISTS(SELECT 1 FROM common_flow_outside_type old WHERE NOT EXISTS(SELECT 1 FROM public.payroll_statements p WHERE to_jsonb(p)=old.value))
 THEN RAISE EXCEPTION 'manual/finalized/other-company/type/history payroll changed'; END IF;
 SELECT jsonb_build_object(
 'rates',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]') FROM public.company_rate_settings t),
 'settings',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]') FROM public.worker_payroll_settings t),
 'tax_conditions',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]') FROM payroll_tax_private.worker_conditions t),
 'attendance',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]') FROM public.attendance_entries t)) INTO source_after;
 IF source_after IS DISTINCT FROM (SELECT value FROM common_flow_source)
 THEN RAISE EXCEPTION 'common flow changed original rate/individual/insurance/attendance settings'; END IF;
 INSERT INTO common_flow_result VALUES(jsonb_build_object('saved',true,'published',true,'payroll_totals_verified',true,
 'public_detail_verified',true,'tax_insurance_conditions_preserved',true,'resident_tax_preserved',true,'save_retry_verified',true,'publish_retry_verified',true,'cas_verified',true,
 'tax_conditions_registered',baseline_tax IS NOT NULL AND baseline_tax<>'null'::jsonb,
 'tax_amount_changed',coalesce(expected_tax->'income_tax_yen' IS DISTINCT FROM baseline_tax->'income_tax_yen' OR expected_tax->'social_yen' IS DISTINCT FROM baseline_tax->'social_yen',false),
 'protected_existing_statement_count',(SELECT count(*) FROM common_flow_protected),
 'recalculated_scopes',(first_result->>'recalculated_scopes')::integer));
END $flow$;
SELECT value FROM common_flow_result;
